-- Seed Batch 2 Saints & demigods lore (missing high-tier Beyonders audit):
-- Sequence 3-4 figures across the pathways, generated from the canonical TS
-- source (src/lib/lore/npcs.ts), same lore_entries INSERT format as the
-- earlier seed migrations. narratorOnly is a TS-only prompt flag (no column),
-- intentionally not persisted. All entries are epoch 5, pathway-keyed, gated
-- to their own sequence (progressive disclosure). Array columns seed as '{}'
-- (never null) to match the non-null npcs/sequences/tags schema.

insert into public.lore_entries (slug, title, category, content, pathway, epoch, city, npcs, sequences, tags, token_count)
values
  ('npc-nast-solomon', 'Nast Solomon — King of the Five Seas, Frenzied Mage', 'npc', 'Nast Solomon is one of the five Pirate Kings of the Fifth Epoch and is widely regarded as the strongest pirate alive, bearing the title "King of the Five Seas." A descendant of the Solomon Family and self-styled Earl of White Maple — a noble rank his father Savigny received from Emperor Roselle — Nast commands the Black Emperor, a formidable pirate vessel, and carries an 800,000-pound bounty. He is approximately 160 years old and hails from the Intis Republic.

He is a Sequence 3 Frenzied Mage of the Black Emperor Pathway, making him a demigod-tier Beyonder. In the Spirit World his form becomes comparable to an ancient giant, whose presence alone makes people subconsciously want to bow their heads. Despite his fearsome reputation he is known for not killing captives, and since claiming dominance of the Five Seas he has enacted sea-passage codes that constrain piracy from escalating to wanton slaughter.

Nast clashed with Loen warships and later met with Klein Moretti, asking Klein about the whereabouts of the Black Emperor Card of Blasphemy in exchange for information about Roselle. By 1358 he came into conflict with Alger Wilson ("Stormbringer") over the Lost City of Newins and the Solomon Empire''s inheritance. He has openly declared his ambition to establish a pirates'' kingdom and ascend to duke, king, or emperor.', 'black-emperor', 5, null, ARRAY['Nast Solomon', 'Black Emperor Solomon', 'Savigny Solomon', 'Klein Moretti', 'Alger Wilson', 'Ludwell'], ARRAY[3], ARRAY['black-emperor-pathway', 'demigod', 'spoiler', 'pirate-king', 'solomon-family', 'frenzied-mage', 'five-seas', 'intis-republic'], 238),
  ('npc-peacock', 'Peacock — Earl of the Fallen, Turncoat Senior Deacon', 'npc', 'Peacock is a Sequence 4 Earl of the Fallen on the Black Emperor Pathway — a Saint-tier Beyonder whose outward face was that of a loyal servant of the Church of the Eternal Blazing Sun. Based in the Trier district of the Intis Republic, he served as a Senior Deacon of the Purifiers and one of the heads of the Inquisition, holding authority over the surrounding areas of Trier — essentially the entire Trier district except for Trier itself. In secret he was aligned with April Fool''s and the School of Truth, and collaborated with that faction to engineer the escape of Sealed Artifact 1-147. When the Overseer Perle was compromised and his treachery threatened exposure, he deployed a wax-figure substitute to maintain the illusion of his presence for days while his real body was concealed elsewhere. He ultimately fled when Saint Viève and Plessy Descartes cornered him. His own words frame his betrayal as pragmatic survival — submission to the great existences before the Crimson apocalypse arrives. As of his last appearance he remains alive, a Saint-level renegade Church inquisitor now operating under the April Fool''s umbrella.', 'black-emperor', 5, null, ARRAY['Peacock', 'Perle', 'Viève', 'Plessy Descartes'], ARRAY[4], ARRAY['black-emperor-pathway', 'saint', 'spoiler', 'april-fools', 'school-of-truth', 'inquisition', 'church-of-the-eternal-blazing-sun', 'intis-republic', 'trier', 'traitor', 'sealed-artifact'], 220),
  ('npc-savigny-solomon', 'Savigny Solomon — Earl of White Maple', 'npc', 'Savigny Solomon was a Sequence 4 Earl of the Fallen of the Black Emperor Pathway, hailing from the Intis Republic and claiming descent from the ancient Solomon Empire. He bore the title Earl of White Maple, bestowed by Roselle Gustav in recognition of a covert arrangement between the two men: Savigny would deploy his pirate forces to plunder Roselle''s opponents along a new sea route, targeting ships of the Feysac Empire, Loen Kingdom, and Feynapotter Kingdom. In exchange, Roselle promised to help him advance to a High-Sequence Beyonder. The deal is recorded in Roselle''s private diary, placing Savigny within the inner orbit of Intis imperial machinations. Savigny is the father of Nast Solomon, the King of the Five Seas, and is counted among the descendants of the Black Emperor Solomon, ancestor of the Solomon Family bloodline. He is deceased by the time of the main narrative. Narrators should treat his role as context for the Solomon Family''s Beyonder legacy and its historical entanglement with Roselle''s imperial ambitions.', 'black-emperor', 5, null, ARRAY['Savigny Solomon', 'Nast Solomon', 'Roselle Gustav', 'Black Emperor Solomon'], ARRAY[4], ARRAY['black-emperor-pathway', 'saint', 'spoiler', 'solomon-family', 'pirate', 'intis-republic', 'roselle-associate', 'deceased'], 196),
  ('npc-mahmosi', 'Mahmosi — The Silent One, Disciple of Silence', 'npc', 'Mahmosi is a Sequence 3 Disciple of Silence of the Chained Pathway and an important member of the Indulgence faction of the Rose School of Thought. He is the student of Abomination Suah, now deceased. A man of mixed Southern and Northern Continental heritage, he presents as middle-aged and gaunt — his face thin to the bone, eye sockets deeply recessed — dressed in a white robe with golden threads, his thick lips sealed shut by dense patterned golden nails, a visceral emblem of his Sequence''s doctrine. His pale-yellow curled hair and brown eyes, the latter carrying an irrepressible maleficence and madness, complete an unmistakably sinister appearance.

By blood, Mahmosi is a descendant of the former kings of the ancient Highlands Kingdom and one of the main leaders of that kingdom''s rebel army against Loen. His dual role — cult demigod and political insurgent — makes him a nexus of supernatural and geopolitical threat in the Southern Continent. He venerates the Mother Tree of Desire and sought her revelation after his operations were disrupted.

During Book One, Loen''s forces (including MI9) attempted to use the mummy of Tutanssess II as bait to draw him out. While Mahmosi fought MI9 alongside Zatwen, Klein Moretti, Sharron, and Maric stole the mummy. The theft was later attributed to Sharron''s advancement ritual.', 'chained', 5, null, ARRAY['Mahmosi', 'Suah', 'Klein Moretti', 'Sharron', 'Maric', 'Zatwen', 'Tutanssess II'], ARRAY[3], ARRAY['chained-pathway', 'demigod', 'spoiler', 'rose-school-of-thought', 'indulgence-faction', 'highlands-kingdom', 'rebel-army', 'mother-tree-of-desire', 'southern-continent', 'book-one'], 233),
  ('npc-zatwen', 'Zatwen — Sequence 4 Puppet of the Rose School of Thought', 'npc', 'Zatwen is a male human Beyonder and Saint-tier operative of the Rose School of Thought''s Indulgence faction, standing at Sequence 4 Puppet on the Chained Pathway. Standing 1.8 meters tall with brown skin, his face is thin and his eyes are recessed like a dried corpse. His mustache extends from his mouth all the way to his ears, black at the root and white outwards, appearing rather sparse and short. A devotee of the Mother Tree of Desire, he serves as mentor to Flight Ken, leader of the Naturism Sect. Zatwen collaborated with Mahmosi in a failed attempt to steal the mummy of Tutanssess II from Loen''s military, only to be outmaneuvered by Klein Moretti, Sharron, and Maric — who took it while Zatwen''s group fought MI9. He subsequently concluded the mummy was taken for Sharron''s advancement ritual and considered seeking a revelation from the Mother Tree. Zatwen also possessed a Sealed Artifact of the Error Pathway; due to the Law of Beyonder Characteristics Convergence, it attracted Amon''s avatar, who took the artifact from him.', 'chained', 5, null, ARRAY['Zatwen', 'Mahmosi', 'Flight Ken', 'Sharron', 'Maric', 'Klein Moretti', 'Amon'], ARRAY[4], ARRAY['chained-pathway', 'saint', 'spoiler', 'rose-school-of-thought', 'indulgence-faction', 'mother-tree-of-desire', 'naturism-sect', 'error-pathway-artifact', 'amon-encounter', 'book-one'], 213),
  ('npc-tutanssess-ii', 'Tutanssess II — Ancient Pharaoh of the Haagenti Plains', 'npc', 'Tutanssess II was the nineteenth King and Pharaoh of the ancient Haagenti Plains on the Southern Continent, a high-sequence Beyonder of the Chained pathway who has long since died. Following his death, his Beyonder characteristic was taken away, and his corpse was mummified according to the traditions of the ancient Highlands Kingdom. The mummy — bound in yellowish-brown cloth with its surface covered in a dark red oily liquid, its face bearing a golden patterned mask with onyx gems set in the eye sockets — was filled with hexes and carried a latent capacity to automatically become a Zombie.

Before the Loen, Intis, and Feynapotter allied forces attacked the Highlands Kingdom, the Pharaoh''s descendants moved the most important batch of mummies to a rebel army''s secret base. Loen forces later stormed that base and recovered the Tutanssess II mummy from its lowest level, planning to deliver it to an unknown military organization in Backlund for research. Before the handover, the mummy was stolen through the combined efforts of Sharron, Maric, and Klein Moretti. It was subsequently used as the key material in Sharron''s advancement ritual to Sequence 4 Puppet, valued for its spiritual richness and hex-laden nature.', 'chained', 5, null, ARRAY['Tutanssess II', 'Sharron', 'Maric', 'Klein Moretti'], ARRAY[4], ARRAY['chained-pathway', 'saint', 'spoiler', 'haagenti-kingdom', 'southern-continent', 'highlands-kingdom', 'deceased', 'mummy', 'pharaoh', 'book-one'], 224),
  ('npc-anthony-stevenson', 'Anthony Stevenson — Archbishop of the Church of the Evernight Goddess', 'npc', 'Anthony Stevenson is one of the thirteen archbishops of the Church of the Evernight Goddess and the person in charge of the Backlund diocese, personally overseeing Saint Samuel Cathedral. A demigod of the Darkness Pathway at Sequence 3 — Horror Bishop — he is a formidable and meticulous ecclesiastical figure. An old man with deeply recessed eyes, he wears the black-and-red archbishop''s robe bearing five Dark Sacred Emblems, his appearance always extremely clean.

When the threat of Trissy Cheek surfaced, Anthony awakened Sealed Artifact 0-17 to contain the matter. Following the True Creator''s interrupted descent ritual in Backlund, he personally led Nighthawks to investigate the altar and the surrounding area. He subsequently oversaw the inquiry into the infiltration of Saint Samuel Cathedral — the culprit eventually identified, with Holy Cathedral assistance, as Gehrman Sparrow, alias of Klein Moretti. Anthony also managed personnel assignments within the Nighthawks: when Crestet Cesimir requested help locating an underground ruin, Anthony assigned Soest''s team but deliberately extracted Leonard Mitchell and routed him toward paranormal casework suited to digesting the Soul Assurer potion — a subtle but deliberate managerial hand in his subordinates'' advancement.', 'darkness', 5, null, ARRAY['Anthony Stevenson', 'Klein Moretti', 'Leonard Mitchell', 'Crestet Cesimir', 'Trissy Cheek'], ARRAY[3], ARRAY['darkness-pathway', 'demigod', 'spoiler', 'church-of-the-evernight-goddess', 'nighthawk', 'backlund', 'archbishop', 'loen-kingdom', 'horror-bishop'], 226),
  ('npc-crestet-cesimir', 'Crestet Cesimir — Goddess''s Sword, High-Ranking Deacon of the Church of the Evernight Goddess', 'npc', 'Crestet Cesimir is one of the nine high-ranking deacons of the Church of the Evernight Goddess and a Sequence 4 Nightwatcher of the Darkness pathway, bearing the Beyonder title Goddess''s Sword. He is also one of the three powerhouses of the Red Gloves division of the Nighthawks. A native of the Loen Kingdom, he has very short golden-brown hair and blackish-green eyes as dark as a forest on a moonless night, typically wearing a black windbreaker and white shirt with both collars propped high to conceal his chin.

His most notable equipment is the Goddess''s Sword, a pure white bone short sword etched with intertwined mystical symbols that elevate his combat effectiveness beyond that of a normal Sequence 4. He was first seen at Sequence 5 (Spirit Warlock) and advanced to Nightwatcher when the war broke out in Backlund.

Cesimir examined Klein Moretti''s soul when Klein applied to advance to Sequence 8 Clown, probing him with a disharmonious song. He fought a Rose Bishop-ranked Aurora Order member during the Death of Lanevus incident. He advises Klein to frame advancement as service to the Goddess rather than personal power.', 'darkness', 5, null, ARRAY['Crestet Cesimir', 'Klein Moretti', 'Evernight Goddess'], ARRAY[4], ARRAY['darkness-pathway', 'saint', 'spoiler', 'church-of-the-evernight-goddess', 'red-gloves', 'nighthawks', 'high-ranking-deacon', 'loen-kingdom', 'backlund', 'aurora-order-antagonist', 'book-one'], 218),
  ('npc-selena', 'Selena — Saint of the Evernight Goddess, Darkness Pathway Nightwatcher', 'npc', 'Saint Selena was a Sequence 4 Nightwatcher of the Darkness Pathway who was active during the Third Epoch, serving as a devotee when the Church of the Evernight Goddess was being established. A High-Sequence Beyonder, her deeds were written in many holy scriptures, and her name became one of the most commonly used among commoners who believed in the Evernight Goddess — a mark of the lasting spiritual impression she left on the faith. After her death, her Beyonder Characteristic turned into the Grade 1 Sealed Artifact known as Saint Selena''s Ashes. The headquarters of the Church of the Evernight Goddess in Tingen City bears her name as the Saint Selena Cathedral. From Ince Zangwill''s advancement and Klein Moretti''s conjectures, it can be confirmed that she was a Sequence 4 Nightwatcher of the Darkness Pathway. She is a figure of historical veneration with no known presence in the current epoch.', 'darkness', 5, null, ARRAY['Saint Selena', 'Ince Zangwill', 'Klein Moretti'], ARRAY[4], ARRAY['darkness-pathway', 'saint', 'spoiler', 'evernight-goddess', 'church-of-the-evernight-goddess', 'third-epoch', 'sealed-artifact', 'historical-figure', 'tingen-city'], 191),
  ('npc-hela', 'Hela — Ferryman, Vice President of the Curly-Haired Baboons Research Society', 'npc', 'Hela is the codename of a transmigrator and one of the vice presidents and initiators of the Curly-Haired Baboons Research Society. Both her former name and real identity are unknown. She is a Sequence 3 Ferryman of the Death pathway — one of those who have gone the furthest down the path to godhood in Book Two. Before reaching her current rank she progressed along the Darkness pathway to Sequence 4, then switched to Death and advanced from Sequence 9 upward. A worshipper affiliated with the Church of the Evernight Goddess, she and Amanises — the Evernight Goddess herself — were best friends before the transmigration. Pale-skinned with light golden hair and dark, light-absorbing eyes, Hela dresses in black with an enigmatic widow-like allure. She operates in Trier and maintains a contracted silver skull messenger. She collaborated with Lumian Lee in the underground catacombs in pursuit of the Samaritan Women''s Spring artifact. Aurore Lee trusted her implicitly, and Lumian first contacted Hela through the skull messenger after Aurore''s death.', 'death', 5, null, ARRAY['Hela', 'Lumian Lee', 'Aurore Lee', 'Franca Roland', 'Evernight Goddess'], ARRAY[3], ARRAY['death-pathway', 'demigod', 'spoiler', 'transmigrator', 'curly-haired-baboons-research-society', 'church-of-evernight-goddess', 'darkness-pathway', 'switched-pathways', 'book-two'], 208),
  ('npc-demoness-of-brown', 'Demoness of Brown — Sequence 3 Unaging of the Demoness Sect', 'npc', 'The Demoness of Brown is a Sequence 3 Unaging of the Demoness Pathway and a former higher-up of the Demoness Sect, active during the Fifth Epoch. Her true name is unknown. She inherited the title by succeeding a predecessor who perished during the Day of Many Disasters, becoming one of nine Sequence 3 Beyonders the Demoness Sect maintained as of 1360 Fifth Epoch. She formerly answered to Judith, a Demoness Sect superior, and counted the Primordial Demoness among her religious devotions before her corruption. At some point she fell under the influence of the Mother Goddess of Depravity, a corruption that severed her prior affiliations and fundamentally altered her allegiance. As an Unaging demigod she represents a significant power within the Demoness Pathway''s upper hierarchy. Narrators should treat her as a corrupted demigod-tier actor no longer bound by Demoness Sect loyalties, whose current agenda aligns with the Mother Goddess of Depravity''s designs.', 'demoness', 5, null, ARRAY['Demoness of Brown', 'Judith', 'Mother Goddess of Depravity'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'corrupted', 'sequence-3', 'unaging', 'book-two'], 192),
  ('npc-demoness-of-gold', 'Demoness of Gold — Sequence 3 Unaging of the Demoness Sect', 'npc', 'The Demoness of Gold is a higher-up of the Demoness Sect whose true name is unknown. Formerly male, she is a Sequence 3 Unaging of the Demoness Pathway, placing her among the most powerful demigod-tier Beyonders operating within the Sect''s hierarchy. She operates under the authority of Judith and holds a position as one of the Sect''s higher-ups.

As of 1359 of the Fifth Epoch, the Demoness Sect counts nine Sequence 3 Beyonders among its ranks; the Demoness of Gold is confirmed to be one of them, per intelligence reported by Madam Magician. Her alias, "Demoness of Gold," is the only identifier attributed to her in available records. She venerates the Primordial Demoness as her religion. Her current status is listed as alive.

For a narrator, she represents a potent demigod-tier threat or asset within any Demoness Sect storyline, possessing Unaging-level abilities whose full scope is not detailed in available records.', 'demoness', 5, null, ARRAY['Demoness of Gold', 'Judith', 'Fors Wall'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'sequence-3', 'unaging', 'fifth-epoch', 'higher-up'], 200),
  ('npc-demoness-of-green', 'Demoness of Green — Sequence 3 Unaging, Higher-Up of the Demoness Sect', 'npc', 'The Demoness of Green is a higher-up of the Demoness Sect, holding the rank of Sequence 3 Unaging of the Demoness Pathway. Her true name is unknown; she is identified only by her title. Formerly male, she follows the Primordial Demoness. Her superior within the Sect is Judith. She came to hold the title by succeeding the previous bearer, who died during the Day of Many Disasters. As of 1360 of the Fifth Epoch, she is one of nine Sequence 3 Beyonders the Demoness Sect commands.', 'demoness', 5, null, ARRAY['Demoness of Green', 'Judith'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'unaging', 'primordial-demoness', 'formerly-male', 'sequence-3'], 120),
  ('npc-demoness-of-orange', 'Demoness of Orange — Sequence 3 Unaging, Higher-Up of the Demoness Sect', 'npc', 'The Demoness of Orange is a high-ranking member of the Demoness Sect whose true name is unknown. Formerly male, she is one of nine Sequence 3 Beyonders the Sect maintains as of 1359 of the Fifth Epoch — a fact reported by Madam Magician (Fors Wall). She walks the Demoness Pathway and has attained the rank of Unaging, the third sequence, placing her in the demigod tier. Her superior within the Sect hierarchy is Judith. The Demoness Sect venerates the Primordial Demoness, and the Demoness of Orange operates as one of the organization''s most powerful internal pillars. Beyond her confirmed existence as part of the Sect''s demigod complement, her individual history and specific activities within the Fifth Epoch remain undisclosed in available records. She is referenced only in passing, establishing the Sect''s overall strength rather than her personal arc. Narrators should treat her as a background power operative — a named but largely anonymous force at the upper echelon of one of the era''s foremost Beyonder factions.', 'demoness', 5, null, ARRAY['Demoness of Orange', 'Judith', 'Fors Wall'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'unaging', 'book-two', 'higher-up', 'formerly-male'], 213),
  ('npc-demoness-of-scarlet', 'Demoness of Scarlet — Sequence 3 Unaging of the Demoness Sect', 'npc', 'The Demoness of Scarlet was a higher-up of the Demoness Sect during the Fifth Epoch, operating under the authority of Judith. Her true name was never revealed. Formerly male, she had ascended to Sequence 3 Unaging of the Demoness Pathway — one of only nine such Beyonders the Sect possessed as of 1359 of the Fifth Epoch, per intelligence relayed by Madam Magician Fors Wall. As an Unaging, she represented the Sect''s demigod tier and a significant power asset for the organization devoted to the Primordial Demoness. She met her end at the hands of Klein Moretti and Leonard Mitchell: Klein acted through a dream projection channeled via the Staff of the Stars, turning her into a Marionette — confirmed at Book 2, Chapter 1135. Her elimination reduced the Demoness Sect''s Sequence 3 count and marked a notable action in Klein''s campaign against the organization.', 'demoness', 5, null, ARRAY['Demoness of Scarlet', 'Klein Moretti', 'Leonard Mitchell', 'Judith', 'Fors Wall'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'sequence-3', 'unaging', 'book-two', 'primordial-demoness', 'deceased'], 188),
  ('npc-demoness-of-silver', 'Demoness of Silver — Sequence 3 Unaging, Higher-up of the Demoness Sect', 'npc', 'The Demoness of Silver is a high-ranking member of the Demoness Sect and a Sequence 3 Unaging of the Demoness Pathway. Her true name is unknown. She is formerly male — a detail that marks the profound transformation wrought by advancement along the Demoness Pathway. She holds the title "Demoness of Silver," a position within the Sect rather than a personal name; the previous bearer of the title perished during the Day of Many Disasters, and she assumed the role as her successor. As of 1360 of the Fifth Epoch, she stands as one of nine Sequence 3 Beyonders the Demoness Sect commands, placing her among the organization''s most formidable assets. Her superior within the Sect is Judith. She venerates the Primordial Demoness. At the Unaging sequence, she operates at the demigod tier — a figure of considerable threat and influence within the Sect''s internal hierarchy.', 'demoness', 5, null, ARRAY['Demoness of Silver', 'Judith'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'unaging', 'sequence-3', 'book-two', 'primordial-demoness'], 190),
  ('npc-jenna', 'Jenna — Demoness of the Unaging, Seven of Cups', 'npc', 'Jenna, true name Celia Bello, is a Sequence 3 Unaging of the Demoness Pathway and a chanteuse from Trier, Intis Republic. Born on May 13th, she is twenty-one at her debut in Book Two and stands as one of the rare Demonesses who was female before her Beyonder transformation. She holds the codename Seven of Cups as a Minor Arcana of the Tarot Club, formerly under Judgement (Xio Derecha) and later under The Chariot, Lumian Lee — with whom she ultimately merges as part of his ascent to the Calamity of Destruction above the sequence. In addition to her Demoness abilities, she wields a Red Priest authority from the Demoness Pathway. Her contracted messenger is Chasel Sávio, an anomalous Rabbit of Knowledge. Jenna also serves as Pope of the Sick Church and formerly acted as an informant for the Church of the Eternal Blazing Sun. She is intensely loyal to allies — Lumian Lee, Franca Roland, Anthony Reid, and Ludwig Phil — and has made enemies of Margot, Hugues Artois, and believers of the Outer Deities. She is notably conscious of the catastrophic nature of Witches and the harm they can bring to ordinary people.', 'demoness', 5, null, ARRAY['Jenna', 'Lumian Lee', 'Franca Roland', 'Xio Derecha', 'Anthony Reid', 'Ludwig Phil', 'Chasel Sávio', 'Elodie', 'Julien Bello'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'tarot-club', 'minor-arcana', 'sick-church', 'intis-republic', 'trier', 'book-two'], 218),
  ('npc-yalenna', 'Yalenna — Demoness of Cyan', 'npc', 'Yalenna, known as the Demoness of Cyan, is a higher-up of the Demoness Sect and one of its nine Sequence 3 Unaging demigods active as of 1359 of the Fifth Epoch. Born male as the child of Judith — Matriarch of the Demoness Sect — and grandchild of Alista Tudor and the Primordial Demoness herself, Yalenna carries an extraordinary bloodline tying her directly to the founding figures of both the Tudor Family and the Demoness Family. She originally advanced through the adjacent Red Priest Pathway, reaching Sequence 5 Reaper before exchanging over to the Demoness Pathway — making her the only demigod-level member of the Demoness Sect who was formerly a Hunter. This cross-pathway history marks her as exceptional within the Sect''s hierarchy. She dresses in a distinctive cyan hunting outfit with thick, long eyebrows noted in her appearance. As one of nine Sequence 3 Saints fielded by the Demoness Sect, she represents a pillar of the organization''s demigod-tier strength. Her survival into the present timeline confirms her vital status as alive and operating at the apex of the Demoness Pathway below the Sequence 2 Catastrophe tier.', 'demoness', 5, null, ARRAY['Yalenna', 'Judith', 'Alista Tudor', 'Primordial Demoness', 'Krismona'], ARRAY[3], ARRAY['demoness-pathway', 'demigod', 'spoiler', 'demoness-sect', 'tudor-family', 'demoness-family', 'switched-pathways', 'red-priest-pathway', 'book-two'], 212),
  ('npc-trissy', 'Trissy — Sequence 4 Despair of the Demoness Pathway', 'npc', 'Trissy is a deceased Beyonder of the Demoness Pathway, having attained Sequence 4: Despair. Born male under the name Tris in Loen Kingdom, she underwent a physical transformation upon reaching Sequence 7: Witch and lived the remainder of her life as a woman. Originally a street tramp controlled by a gang of thugs, she joined the Theosophy Order and rose through the Demoness Pathway before affiliating with the Demoness Sect. During the events of Book One, Trissy served as a vessel for the Primordial Demoness. Following the death of her lover Edessak Augustus, she submitted herself fully to the Primordial Demoness in pursuit of revenge — an act Klein Moretti privately attributed to Stockholm syndrome. Despite this submission, she ultimately turned that power toward sacrifice, destroying George III''s Apotheosis Ritual at the cost of her own life on December 3rd, 1350. Her principal enemies were George Augustus III and Stratford, both dead. Narrators should treat her as a tragic, morally complex figure whose final act was redemptive rather than villainous.', 'demoness', 5, null, ARRAY['Trissy', 'Edessak Augustus', 'George Augustus III', 'Stratford', 'Klein Moretti', 'Reinette Tinekerr'], ARRAY[4], ARRAY['demoness-pathway', 'saint', 'spoiler', 'demoness-sect', 'theosophy-order', 'loen-kingdom', 'deceased', 'primordial-demoness-vessel', 'book-one'], 213),
  ('npc-flora-jacob', 'Flora Jacob — Saint of the Error Pathway', 'npc', 'Flora Jacob was a Sequence 4 Parasite of the Error Pathway and a scion of the ancient Jacob Family. She traveled to Backlund in search of her ancestral bloodline''s secret treasure, but was severely injured and forced to take refuge in the city''s sewers. To survive discreetly, she parasitized a rat — a desperate measure that slowly eroded her human identity as the host''s instincts and hormones bled into her psyche. She clandestinely recruited Hazel Macht as her Beyonder disciple, guiding the young woman into the Error Pathway with the probable long-term intent of cultivating Hazel to higher sequences so she could seize her body and absorb her Beyonder Characteristics to restore herself. She may also have meddled with Fors Wall''s dreams in pursuit of the Jacob treasure. Her deterioration was not accidental: Amon had deliberately excised from her potion''s knowledge the one countermeasure — maintaining continuous dialogue with a human — that might have arrested her loss of control. Recognizing her instability, Klein moved against her. She ultimately fell to Amon, who absorbed her after she was pushed to the brink of losing control. Amon later remarked that she had received a poor education in mysticism.', 'error', 5, null, ARRAY['Flora Jacob', 'Hazel Macht', 'Amon', 'Pallez Zoroast', 'Jacob'], ARRAY[4], ARRAY['error-pathway', 'saint', 'spoiler', 'jacob-family', 'backlund', 'deceased', 'book-one', 'parasite', 'loen-kingdom'], 228),
  ('npc-kisma', 'Kisma — Saint Tenebrous, Black Knight of the Aurora Order', 'npc', 'Kisma, known by his alias Saint Tenebrous, is one of the five Saints of the Aurora Order and serves as the Order''s overseer for the Loen Kingdom. A Sequence 4 Black Knight of the Hanged Man Pathway, his young and handsome features are perpetually shrouded by a faint curtain of darkness. As a Black Knight, Kisma possesses the ability to graze the souls of Beyonders and channel fragments of their abilities as his own — a predatory power that makes him exceptionally versatile in combat. Among the souls he has absorbed is that of a Sequence 4 Shaman King of the Moon Pathway, granting him cross-pathway capability. Kisma is closely allied with Botis, the Aurora Order''s Saint of Secrets. He identified Fors Wall as a potential link to the Abraham Family and relayed that intelligence to Botis, thereby triggering the trap that led to Fors''s capture. When the Tarot Club launched their counter-offensive against Botis, Kisma intervened to support his fellow Saint but was ultimately forced to withdraw. He is a devotee of the True Creator and remains active in the Loen Kingdom theater.', 'hanged-man', 5, null, ARRAY['Kisma', 'Botis', 'Fors Wall'], ARRAY[4], ARRAY['hanged-man-pathway', 'saint', 'spoiler', 'aurora-order', 'loen-kingdom', 'true-creator', 'black-knight', 'soul-grazer'], 218),
  ('npc-leomaster', 'Leomaster — Saint of Darkness, Black Knight of the Aurora Order', 'npc', 'Leomaster, known by his epithet the Saint of Darkness, is a Sequence 4 Black Knight of the Hanged Man Pathway and one of the seven saints of the Aurora Order. In his natural state he presents as a weathered man with raven-black hair and a plain linen robe. He introduced himself to Klein Moretti during an encounter in the night dream within the Sea of Ruins as an ascetic of a religious organization.

His condition is singular: exposure to a full-body mirror inside a black cloister within the Sea of Ruins fractured his psyche into two opposed personalities. His good side venerates the Ancient Sun God, while his evil side, which manifests as a nearly 2.5-metre armored black knight with deep crimson eyes and a long broad black sword, worships the True Creator and actively attempts to destroy the good side. The two halves are locked in permanent internal conflict, and Leomaster remains trapped somewhere within the Sea of Ruins as a result. His vital status is listed as alive, with his fate unresolved as of Book One.', 'hanged-man', 5, null, ARRAY['Leomaster', 'Klein Moretti'], ARRAY[4], ARRAY['hanged-man-pathway', 'saint', 'spoiler', 'aurora-order', 'sea-of-ruins', 'split-personality', 'ancient-sun-god', 'true-creator', 'book-one'], 196),
  ('npc-seids', 'Seids — Clairvoyant of the Moses Ascetic Order', 'npc', 'Seids is a Sequence 3 Clairvoyant of the Hermit Pathway and one of the Ten Pillars of the Moses Ascetic Order. A tall, thin man of dark-gray hair who dresses as a warlock, he is a devotee of the Hidden Sage and had spent years stationed in Avalon researching mysticism. When the Tarot Club launched its operation to hunt the Hidden Sage, Seids fought The Chariot — Lumian Lee — at the Moses Ascetic Order''s headquarters. As a Sequence 3 Clairvoyant, Seids occupies a rank above the Saint tier within the Hermit Pathway, making him one of the most formidable Beyonders in the Order. His position as a Pillar reflects his standing as a senior member of the Order and a stalwart defender of its patron deity.', 'hermit', 5, null, ARRAY['Seids', 'Lumian Lee'], ARRAY[3], ARRAY['hermit-pathway', 'clairvoyant', 'spoiler', 'moses-ascetic-order', 'hidden-sage', 'pillar', 'tarot-club-antagonist'], 148),
  ('npc-kmerolo', 'Kmerolo — Pillar of the Moses Ascetic Order (Trier Region)', 'npc', 'Kmerolo was a Pillar of the Moses Ascetic Order responsible for the Trier region in the Intis Republic. A devotee of the Hidden Sage, he attained the Saint tier of the Hermit pathway at Sequence 4, bearing the sequence name Mysticologist. His subordinate Nikila supplied him with corrupted knowledge drawn from Knowledge Moor, which gradually consumed him. Cattleya tracked Kmerolo to his last known location but arrived only to find he had vanished after entering Underground Trier. He left behind dense, intertwined complex symbols and letters formed with his blood and flesh — eroding the surrounding rocks and soil, bright red and dazzling — evidence of a mind unraveling under forbidden lore. His ultimate fate remains unknown. His corruption and disappearance represent a significant intelligence gap for those monitoring the Hermit pathway''s organized factions in Intis.', 'hermit', 5, null, ARRAY['Kmerolo', 'Nikila', 'Cattleya'], ARRAY[4], ARRAY['hermit-pathway', 'saint', 'spoiler', 'moses-ascetic-order', 'trier', 'intis-republic', 'corruption', 'knowledge-moor', 'pillar'], 192),
  ('npc-ohayes', 'Ohayes — Pillar of the Moses Ascetic Order', 'npc', 'Ohayes is a deceased male human Beyonder and one of the Ten Pillars of the Moses Ascetic Order, a secret organization devoted to the Hidden Sage. He attained Sequence 4 — Mysticologist — on the Hermit Pathway, placing him at the Saint tier and in a senior leadership position within the Order. His death is confirmed in canon (Book Two), though the circumstances and the identity of his killer are not recorded on his wiki page. Narrators should treat Ohayes as a background figure of institutional weight: his Mysticologist rank signals high attainment in the Hermit Pathway, and his standing as one of the Ten Pillars marks him as a named senior figure in the Moses Ascetic Order during the era of Book Two. The Order itself was later destroyed in the Fifth Epoch during the operation Hunting Hidden Sage.', 'hermit', 5, null, ARRAY['Ohayes'], ARRAY[4], ARRAY['hermit-pathway', 'saint', 'spoiler', 'moses-ascetic-order', 'hidden-sage', 'pillar', 'deceased', 'book-two'], 168),
  ('npc-grove-augustus', 'Grove Augustus — Prince of Sonia, Chaos Hunter', 'npc', 'Grove Augustus is a prince of the Loen Kingdom''s ruling Augustus Family and a Sequence 3 Chaos Hunter of the Justiciar Pathway — the demigod tier of a pathway aligned with law, order, and the pursuit of justice. Distinguished by his oblong face, white hair, curled arc-shaped beard, and thick eyebrows, he carries the bearing of both royalty and a seasoned Beyonder operative.

He operates under MI9, Loen''s military intelligence apparatus, and is tasked with joint oversight of the Blood Emperor Alista Tudor''s underground ruins no. 1, a role he shares with Georgina Augustus. The Blood Emperor''s ruins represent one of the kingdom''s most sensitive containment assignments — a post demanding both his sequenced power and his institutional standing within the Augustus dynasty.

During George III''s Apotheosis Ritual, Grove wielded Sealed Artifact 0-36, the Thorned Crown — a Grade 0 sealed artifact — underscoring his position as one of the kingdom''s most capable demigod assets deployed in moments of existential state crisis. His vital status remains alive at the close of Book One.', 'justiciar', 5, null, ARRAY['Grove Augustus', 'Georgina Augustus', 'Alista Tudor', 'George Augustus III', 'William Augustus I', 'William Augustus VI', 'Edessak Augustus', 'Jevington Augustus'], ARRAY[3], ARRAY['justiciar-pathway', 'demigod', 'chaos-hunter', 'spoiler', 'augustus-family', 'loen-kingdom', 'mi9', 'royalty', 'sealed-artifact', 'book-one'], 220),
  ('npc-amyrius-rieveldt', 'Amyrius Rieveldt — Imperative Mage, Defence Minister of Loen', 'npc', 'Amyrius Rieveldt is a Sequence 4 Imperative Mage of the Justiciar Pathway and one of the highest-ranking military figures in the Loen Kingdom. A middle-aged gentleman of strict, old-fashioned bearing, he served as the supreme naval commander of the Central Sonia Sea before being transferred back to Backlund — likely the result of a scheme by his elder brother, Earl Rieveldt. He subsequently rose to head the Ministry of Defense. Amyrius is grounded and restrained in his use of Beyonder powers; even in high-stakes card games he relies on personal pressure rather than supernatural ability. His personal life was marked by tragedy when his mistress, Cynthia, was eroded by the Mother Tree of Desire and had to be purified. He received a warning from the Twilight Hermit Order while Klein Moretti — acting as a stand-in — impersonated him for three days on Oravi Island. Amyrius holds ties to the Imperial Navy and the Ministry of Defense, and is flanked by his secretary Luan. He is a significant political and military power in Book One Loen, operating at the saint tier of the Justiciar sequence.', 'justiciar', 5, null, ARRAY['Amyrius Rieveldt', 'Cynthia', 'Luan', 'Bilt Brando', 'Earl Rieveldt'], ARRAY[4], ARRAY['justiciar-pathway', 'saint', 'spoiler', 'loen-kingdom', 'imperial-navy', 'ministry-of-defense', 'military', 'oravi-island', 'book-one'], 215),
  ('npc-celt', 'Celt — MI9 Justiciar Demigod', 'npc', 'Celt is a male human demigod of the Justiciar Pathway and an agent of MI9 operating out of Backlund in the Loen Kingdom. Handsome and composed, he appears to be in his forties — black-haired with golden eyes, dressed in a well-ironed suit that projects mature elegance. His sequence rank is Saint (Sequence 4), though his precise sequence name within the Justiciar line remains unknown. He carries a Traveler''s Ring on his right hand, a Beyonder artifact that grants him the spatial mobility of a Sequence 5 Traveler.

As a field-capable demigod, Celt is deployed on high-stakes MI9 operations. He appeared at Capim''s villa following a confrontation involving the Hero Bandit Black Emperor. Later, he co-led a trap for the Rose School of Thought at Pritz Harbor alongside Georgina Augustus, using the Tutanssess II mummy as bait — an operation compromised when Klein Moretti stole the mummy before their eyes. He subsequently joined archbishops of the three major churches to investigate the collapsed forest where demigod Botis died, finding only a Hermit card.

Narrators should present Celt as a measured intelligence demigod accustomed to controlling situations who nonetheless encounters setbacks at critical junctures.', 'justiciar', 5, null, ARRAY['Celt', 'Georgina Augustus', 'Botis', 'Klein Moretti'], ARRAY[4], ARRAY['justiciar-pathway', 'saint', 'demigod', 'spoiler', 'mi9', 'loen-kingdom', 'backlund', 'intelligence-agent', 'rose-school-of-thought-antagonist'], 193),
  ('npc-georgina-augustus', 'Georgina Augustus — Duchess and Justiciar Saint of MI9', 'npc', 'Georgina Augustus is a Saint-tier Beyonder of the Justiciar Pathway and a Duchess of the Augustus Family, one of Loen Kingdom''s great noble bloodlines. She operates in Backlund as an agent of MI9, the kingdom''s military intelligence service, placing her at the intersection of aristocratic power and state espionage. Her Sequence 4 sequence name has not been revealed. In appearance she favours a black evening gown and a golden mask; she has been seen wearing a Thorned Crown, a notable Beyonder item she wielded on at least a temporary basis. During the events of Volume 4 she worked alongside Celt to set up a trap for the Rose School of Thought at Pritz Harbor, using the Tutanssess II mummy as bait. The operation was foiled when Klein Moretti stole the mummy before their eyes — an outcome that led Georgina to characterise Klein as "a very cunning fellow who''s good at deceit." Her combination of aristocratic standing, Justiciar Saint power, and MI9 affiliation makes her a formidable figure in Loen''s covert landscape, though she remains largely in the background of the main narrative.', 'justiciar', 5, null, ARRAY['Georgina Augustus', 'Celt', 'Klein Moretti'], ARRAY[4], ARRAY['justiciar-pathway', 'saint', 'spoiler', 'mi9', 'augustus-family', 'loen-kingdom', 'backlund', 'nobility', 'duchess', 'intelligence-agent', 'thorned-crown'], 215),
  ('npc-xio-derecha', 'Xio Derecha — Judgment of the Tarot Club', 'npc', 'Xio Derecha is a female Beyonder of the Justiciar Pathway, born into the Dere noble family of East Tucker County, Loen. Her father, Mason Dere — leader of the Household Guards Division and captain of the royal guards — was executed on charges of participating in a revolt; the family was stripped of its title, and Xio moved with her mother and younger brother Rio to East Chester before coming to Backlund alone to restore the family name. Born a half-Arbiter, she was constitutionally limited to the Justiciar Pathway. She rose through bounty hunting and MI9 informant work, eventually serving as Colonel and Deputy Team Leader of MI9''s National Security and Counter-Espionage Team. By the events of Book One she has reached Sequence 4, Imperative Mage. Her Tarot Club codename is Judgment; she holds Major Arcana rank. Close friends with Fors Wall and Audrey Hall, she joined the Tarot Club partly to support Fors. Her contracted messenger, Ongla, is a transparent, crystalline ice-blue jellyfish with many tentacles. Driven by a fierce sense of justice, she is willing to use physical persuasion when words fail. She later advances to Deputy Director of MI9 in Book Two.', 'justiciar', 5, null, ARRAY['Xio Derecha', 'Fors Wall', 'Audrey Hall', 'Mason Dere', 'Rio Derecha', 'Franca Roland'], ARRAY[4], ARRAY['justiciar-pathway', 'saint', 'spoiler', 'tarot-club', 'mi9', 'loen-kingdom', 'backlund', 'church-of-the-fool', 'bounty-hunter', 'contracted-messenger'], 221),
  ('npc-nibbs-odora', 'Nibbs Odora — High Summoner of the Odora Family', 'npc', 'Nibbs Odora is a powerful Sanguine of the Odora family, a Moon pathway Beyonder who has reached Sequence 3 as a High Summoner. Active since the Fourth Epoch, his extraordinary lifespan has nonetheless been corroded by time, forcing him to spend prolonged periods lying in a cold coffin. He is the grandfather of Cosmi Odora.

When Emlyn White sought aid against Bishop Utravsky — a matter his peers deemed unworthy of antagonizing the bishop — Nibbs maneuvered Emlyn into praying to the Fool, calculating that if the hidden existence failed to respond, Emlyn was simply expendable. His true intent was to forge a connection between this mysterious deity and the Sanguines as a whole. The gambit ultimately succeeded; even Nibbs came to believe their ancestor Lilith had begun showing genuine concern for Emlyn. He is based in the Loen Kingdom, within the Northern Continent''s Trunsoest Empire.', 'moon', 5, null, ARRAY['Nibbs Odora', 'Cosmi Odora', 'Emlyn White', 'Lilith'], ARRAY[3], ARRAY['moon-pathway', 'demigod', 'spoiler', 'sanguine', 'odora-family', 'fourth-epoch', 'loen-kingdom', 'northern-continent', 'trunsoest-empire'], 210),
  ('npc-alexis', 'Alexis — Sanguine Earl and Shaman King', 'npc', 'Alexis is a Sanguine Earl and a Sequence 4 Shaman King of the Moon pathway, a direct descendant of the legendary Round Moon Duke Olmer. Born in Feynapotter City within the Feynapotter Kingdom, he was a follower of the Mother Goddess of Depravity and formerly affiliated with Sanguine society. Alexis transported the Mother Card of Blasphemy — one of the Cards of Blasphemy — to the New City of Silver, where its power healed the corruption known as Gift of the Land. The Sealed Artifact then escaped from its seal, and in the process the Mother Card absorbed Alexis''s life entirely. He died in that act. His canonical significance lies not in direct combat but in his fatal stewardship of a dangerous relic: a high-ranking Beyonder whose life was consumed by the artifact he delivered. Narrators should present him as a figure of Sanguine aristocracy and religious observance — a descendant of Olmer whose final mission ended in his complete absorption by the Mother Card.', 'moon', 5, null, ARRAY['Alexis', 'Olmer'], ARRAY[4], ARRAY['moon-pathway', 'saint', 'spoiler', 'sanguine', 'feynapotter-kingdom', 'mother-goddess-of-depravity', 'cards-of-blasphemy', 'book-two', 'deceased'], 201),
  ('npc-klarman', 'Klarman — Shaman King of the Rose School of Thought', 'npc', 'Klarman was a Sequence 4 Shaman King of the Moon Pathway, nearly 1,400 years old at the time of his death, sustained by the Primordial Moon''s blessings. Originally active on the Southern Continent in the early Fifth Epoch, he vanished from public record — believed by many to have been hunted down by the Church of Death or the Rose School of Thought, or to have died of old age in some unknown place. In truth he had joined the Rose School of Thought as one of its saints, serving as an Oracle and wielding the highest authority in West Balam. He authored the Book of Secrets, which Klein Moretti later obtained through Sharron. Klarman was last publicly seen enticing people to sacrifice an entire train to the Primordial Moon; Klein destroyed the ritual. During the 1350 World War, he attacked a Church of the Evernight Goddess city base in the Southern Continent, where he was killed by Emlyn White, Sharron, Reinette Tinekerr, and Gehrman Sparrow (Klein Moretti). Emlyn White subsequently used his Beyonder characteristic to advance to Sequence 4.', 'moon', 5, null, ARRAY['Klarman', 'Emlyn White', 'Sharron', 'Reinette Tinekerr', 'Klein Moretti'], ARRAY[4], ARRAY['moon-pathway', 'saint', 'spoiler', 'rose-school-of-thought', 'oracle', 'west-balam', 'southern-continent', 'primordial-moon', 'book-one'], 234),
  ('npc-mistral', 'Mistral — Sanguine Earl, Shaman King', 'npc', 'Earl Mistral is a Sanguine Earl operating in Backlund during Book One. A thin, tall, upright figure with near-silver hair and bright blood-red eyes, he occupies Sequence 4 — Shaman King — on the Moon pathway, placing him at Saint tier within Sanguine society. His religion is the Sanguine Ancestor Lilith, binding him to the core theological tradition of his species. Mistral was initially partnered with Ernes Boyar to test the Tarot Club — the powerful backer concealed behind Emlyn White. Subsequently, through Emlyn acting as an intermediary, Mistral coordinated with Sharron and Maric, marshaling Sanguine members in a joint operation to deal with key figures of the Rose School of Thought active in Backlund.', 'moon', 5, null, ARRAY['Mistral', 'Ernes Boyar', 'Emlyn White', 'Sharron', 'Maric'], ARRAY[4], ARRAY['moon-pathway', 'saint', 'spoiler', 'sanguine', 'backlund', 'loen-kingdom', 'rose-school-of-thought', 'tarot-club-adjacent', 'book-one'], 178),
  ('npc-oxyto', 'Oxyto — Shaman King of the Rose School of Thought', 'npc', 'Oxyto is a Saint-tier Beyonder affiliated with the Rose School of Thought''s Primordial Moon Faction. Formerly male, Oxyto transitioned to female upon advancing through the Chaos Primogenitor Pathway — as all Beyonders of that pathway do at Sequence 5 (Banshee). In the formerly male form, Oxyto appeared as a handsome young man with pale skin and slightly curly black shoulder-length hair. In the current female form, Oxyto is luminously beautiful with a face radiating maternal brilliance, and arched hands and feet ending in sharp, coldly gleaming nails. Oxyto holds the rare distinction of dual Sequence 4 advancement: Shaman King on the Moon Pathway and Madame on the Chaos Primogenitor Pathway, making them both a Multiple Pathways Beyonder and a Boon Recipient. Within the Rose School of Thought — a cult devoted to the Mother Goddess of Depravity — Oxyto represents a convergence of Moon and Chaos power operating at the Saint threshold, a spoiler-significant data point for narrators tracking the Rose School''s senior membership.', 'moon', 5, null, ARRAY['Oxyto'], ARRAY[4], ARRAY['moon-pathway', 'chaos-primogenitor-pathway', 'saint', 'spoiler', 'rose-school-of-thought', 'primordial-moon', 'multiple-pathways-beyonder', 'boon-recipient', 'shaman-king', 'madame'], 210),
  ('npc-agrippina', 'Agrippina — Archbishop of the Gaia Diocese', 'npc', 'Agrippina is a Saint-tier demigod of the Mother Pathway and Archbishop of the Church of the Earth Mother''s Gaia diocese. She is a mature, brown-haired, brown-eyed, stunning woman who appears to be in her thirties; she wears a brown clergyman''s robe and a nun''s wimple with wheat patterns and exudes a maternal aura, as if she had nurtured many children. Her Sequence 4 title is listed as unknown in canon. Agrippina is associated with the Feynapotter Kingdom. During events at Port Santa she assisted in locating Loki, who had kidnapped Ludwig in preparation for Loki''s own Sequence 4 ritual. Her willingness to personally act in a matter involving Loki underscores her considerable standing as a senior ecclesiastical authority. Narrators should present her as a capable, maternally imposing Church power-broker; her precise upper abilities are not detailed in canon and should not be invented.', 'mother', 5, null, ARRAY['Agrippina', 'Loki', 'Ludwig'], ARRAY[4], ARRAY['mother-pathway', 'saint', 'spoiler', 'church-of-the-earth-mother', 'archbishop', 'feynapotter-kingdom', 'port-santa', 'book-two'], 178),
  ('npc-claude', 'Claude — Mechanical Fanatic Saint of the Paragon Pathway', 'npc', 'Claude is a male human Saint of the Paragon pathway, originating from Trier in the Intis Republic. A former clergy member of the Church of the God of Steam and Machinery, he was sent to the Deep Valley Cloister for repentance following a pollution encounter with The Hostel. Contrary to expectations, Claude secretly completed a 90% mechanical ascension during his exile: he replaced nearly all of his body with mechanical components, retaining only his organic brain — his temples encased in a transparent special material and powered by spiritual gems — while becoming a mechanical giant over three meters tall, with one emerald and one ruby cybernetic eye. He justified this self-modification as the true will of the God of Steam and Machinery, proclaiming that flesh was incompetent and limited. Claude also used humans as raw material to transmute and refine the spiritual gems powering his construct body. In Fall 1358 he was confronted by Horamick Haydn and the Machinery Hivemind; the arrival of an unknown wilderness and the Celestial Master''s sigh allowed him to escape pursuit. His vital status remains unknown. He is a fanatical, antisocial figure whose extremist theology places him at odds with the mainstream church hierarchy.', 'paragon', 5, null, ARRAY['Claude', 'Horamick Haydn'], ARRAY[4], ARRAY['paragon-pathway', 'saint', 'spoiler', 'church-of-the-god-of-steam-and-machinery', 'deep-valley-cloister', 'mechanical-ascension', 'intis-republic', 'trier', 'fanatic', 'book-two'], 230),
  ('npc-jack-walton', 'Jack Walton — Prior of the Deep Valley Cloister', 'npc', 'Jack Walton is a Saint-level Beyonder of the Paragon pathway and the current Prior of the Deep Valley Cloister, a religious house affiliated with the Church of the God of Steam and Machinery. He is a monk in bearing — short, thick hair and a beard. As Prior, Walton holds institutional authority within the cloister and occupies a position of weight inside the Church''s infrastructure in Trier, within the Intis Republic. He sits at Sequence 4 (Saint) of the Paragon pathway, placing him among the formidable mid-tier figures of the Church. No named allies or enemies are recorded in the canonical sources, and his history beyond his administrative role at Deep Valley Cloister has not been detailed in the novel through Chapter 1099 of Book Two. Narrators should treat him as a mid-authority Church official — significant enough to grant or deny access to cloister resources and capable of posing a meaningful threat at Sequence 4, but not among the apex figures of the Church.', 'paragon', 5, null, ARRAY['Jack Walton'], ARRAY[4], ARRAY['paragon-pathway', 'saint', 'spoiler', 'church-of-the-god-of-steam-and-machinery', 'deep-valley-cloister', 'intis-republic', 'trier', 'prior', 'monk', 'book-two'], 193),
  ('npc-tony-twain', 'Tony Twain — War Bishop of the Iron and Blood Cross Order', 'npc', 'Tony Twain is the most powerful Vice-President of the Iron and Blood Cross Order, a militant Intisian organization devoted to making the supernatural known to all humanity. A Sequence 3 War Bishop of the Red Priest Pathway, he operates directly under the Order''s President, Diest, and makes no effort to conceal his power — a deliberate expression of the Order''s doctrine of openness. His personality is defined by unbridled arrogance and extreme confidence in his own strength, which he deploys to shatter the doubts of others rather than offer persuasion.

During the Fifth Epoch, Tony pursued Ince Zangwill after repeated killings of Order members, tracking him to a ship filled with ordinary people. He publicly displayed his abilities without restraint, then extracted a decoy disguised as Ince — only for Ince to escape by using Sealed Artifact 0-08 (Quill of Alzuhod) to confuse Tony''s hunter intuition. In 1358, Tony and Diest entered the briefly-opened gate to Fourth Epoch Trier as part of the Order''s machinations, where they fought the out-of-control angel Vermonda Sauron before being forced to flee when Red Angel Medici appeared. His stated long-term goal is to advance to Sequence 2 Conqueror.', 'red-priest', 5, null, ARRAY['Tony Twain', 'Diest', 'Ince Zangwill', 'Vermonda Sauron', 'Red Angel Medici'], ARRAY[3], ARRAY['red-priest-pathway', 'demigod', 'spoiler', 'iron-and-blood-cross-order', 'war-bishop', 'intis-republic', 'northern-continent', 'vice-president', 'book-one', 'book-two'], 229),
  ('npc-gusain', 'Gusain — Iron-blooded Knight and Member of the Iron and Blood Cross Order', 'npc', 'Gusain is a Book Two Beyonder operating across two pathways simultaneously: a Sequence 4 Iron-blooded Knight of the Red Priest Pathway and a Sequence 4 Madame of the Chaos Primogenitor Pathway, making him a rare multi-pathway Saint. He is a member of the Iron and Blood Cross Order and holds the title of Count. Residing in Morora, Lenburg, Gusain initially presents as an educated, upper-class male in his early thirties — thin-faced, gentle blue eyes, well-dressed. He directly confronts Lumian Lee, delivering a cold philosophy: ''Eagles don''t mingle with sparrows.'' His attempt to ascend further through a pact ritual is fatally undermined when Lumian Lee sabotages the ceremony, causing Gusain to instead become an unwilling boon bestowed of the Mother Goddess of Depravity — the Great Mother — a transformation accompanied by a shift to a female form consistent with the Madame sequence. He is subsequently killed by Wanak. His dual-pathway Saint status and association with the Iron and Blood Cross Order mark him as a significant antagonist at the boundary between two distinct Beyonder traditions.', 'red-priest', 5, null, ARRAY['Gusain', 'Lumian Lee', 'Wanak', 'Mother Goddess of Depravity'], ARRAY[4], ARRAY['red-priest-pathway', 'chaos-primogenitor-pathway', 'saint', 'spoiler', 'iron-and-blood-cross-order', 'book-two', 'multi-pathway', 'deceased', 'antagonist', 'lenburg', 'morora'], 220),
  ('npc-wanak', 'Wanak — Iron-blooded Knight of Morora', 'npc', 'Wanak is a male human resident of Morora in Lenburg, known as the most dangerous person in that settlement. A Red Priest pathway Beyonder, he held the Sequence 4 rank of Iron-blooded Knight — though described as a "half" Sequence 4, he had nonetheless fundamentally surpassed a Sequence 5 Beyonder. He served as the proxy of Salinger''s Blood Banner in Morora until displaced by Lumian Lee''s arrival. Outside his Beyonder activities, he owned Dades Agricultural Company and held a monopoly on the grain supply flowing from surrounding farms into Morora. His appearance was striking and menacing: hair stained blood-red, iron-black eyes, sharp facial features, and a fierce aura — wearing a thin white shirt with the top two buttons undone even in cold winter. His history includes a stint as an experimental subject from which he escaped, after which he lived as an apparent normal. He is deceased.', 'red-priest', 5, null, ARRAY['Wanak', 'Lumian Lee'], ARRAY[4], ARRAY['red-priest-pathway', 'saint', 'spoiler', 'morora', 'lenburg', 'salinger-blood-banner', 'deceased', 'book-two'], 188),
  ('npc-murskogan', 'Murskogan — Light Culler, Leader of the Court Chasers', 'npc', 'Murskogan was a Giant and a Sequence 3 Silver Knight of the Twilight Giant pathway. Known by the epithets Light Culler and Court Chaser, he led the Court Chasers under Giant King Aurmir in the 2nd Epoch, hunting dragons, elves, devils, demonic wolves, and phoenixes. After a certain incident, he transferred his allegiance to the Dark Angel Sasrir.

Facing a saint''s limited lifespan, Murskogan employed a secret life-domain technique binding his spirit to living statues in the Giant King''s Court, granting extreme longevity at the cost of confinement to a narrow range near those statues and likely preventing him from manifesting his Mythical Creature Form.

During a 5th Epoch City of Silver expedition into the Giant King''s Court, his ambush instantly killed one explorer. After a grueling battle supported by Lovia Tiffany and Derrick Berg, Colin Iliad destroyed the binding statues, severing Murskogan''s life source and killing him. Before his spirit fully dissipated, Klein Moretti used a Paper Angel to extract the Silver Knight advancement ritual, supplementary ingredients, and the status of the sleeping Sasrir. Colin later used that formula to advance to Silver Knight himself.', 'twilight-giant', 5, null, ARRAY['Murskogan', 'Colin Iliad', 'Sasrir', 'Klein Moretti', 'Derrick Berg', 'Lovia Tiffany'], ARRAY[3], ARRAY['twilight-giant-pathway', 'demigod', 'spoiler', 'giant-kings-court', 'court-chasers', 'forsaken-land-of-the-gods', 'deceased', 'book-one'], 218),
  ('npc-randall-valentinus', 'Randall Valentinus — Deep Blue Officiant', 'npc', 'Randall Valentinus is a Cardinal of the Church of the Lord of Storms and Archbishop of the Holy Wind Cathedral in Backlund, Loen Kingdom. A Saint-rank Beyonder of the Tyrant Pathway, he carries the title "Deep Blue Officiant." He is a middle-aged man with a domineering demeanor — dark blue hair, large earlobes, and eyes that seem to constantly hide lightning and storms within them.

He holds dual authority as both a senior ecclesiastical figure and an operative of the Mandated Punishers, placing him at the intersection of the Church''s public administration and its covert enforcement arm. He coordinates with high-ranked allies including Horamick Haydn, Arianna, Celt, and Anthony Stevenson on sensitive investigations.

Randall investigated the ruins of the Blood Emperor alongside Arianna and Horamick Haydn, failing to find anything to compromise the Augustus Family. Later, after the Tarot Club''s confrontation with Botis, he and his associates convened a joint meeting with the Machinery Hivemind, Mandated Punishers, and MI9 to assess the mysterious tarot-card-coded organization — it was Randall himself who moved to give the group a formal name, proposing they stop referring to it by mouthful descriptions.', 'tyrant', 5, null, ARRAY['Randall Valentinus', 'Horamick Haydn', 'Arianna', 'Celt', 'Anthony Stevenson', 'Leonard Mitchell'], ARRAY[4], ARRAY['tyrant-pathway', 'saint', 'spoiler', 'church-of-the-lord-of-storms', 'mandated-punishers', 'cardinal', 'archbishop', 'loen-kingdom', 'backlund', 'deep-blue-officiant'], 226),
  ('npc-anthony-reid', 'Anthony Reid — Four of Swords, Acting Pope of the Sick Church', 'npc', 'Anthony Reid is a retired soldier from the West Midseashire Coast of the Intis Republic, turned information broker, and a Beyonder of the Visionary Pathway at Sequence 4 — Manipulator, placing him at the Saint tier. He operates out of Trier and holds the Tarot Club codename Four of Swords, currently a Minor Arcana under The Chariot (Lumian Lee), having previously served under Justice (Audrey Hall). Beyond his broker activities, Reid holds the position of Acting Pope of the Sick Church and is affiliated with the Psychology Alchemists. His background is marked by anguish and righteous anger — his own words — forged through years of hardship following military service. His enemies include the deceased Philip and Hugues Artois, as well as believers of Outer Deities, reflecting a history of conflict with malevolent Beyonder factions. Close associates include Lumian Lee, Franca Roland, Jenna, Ludwig Phil, and the Knight of Swords (Maric). He maintains religious ties to both the Church of the Fool and the Church of the God of Steam and Machinery. Narrators should treat him as a well-connected Saint-tier Visionary asset embedded in Intis''s underground networks.', 'visionary', 5, null, ARRAY['Anthony Reid', 'Lumian Lee', 'Audrey Hall', 'Franca Roland', 'Maric', 'Jenna', 'Ludwig Phil', 'Philip', 'Hugues Artois'], ARRAY[4], ARRAY['visionary-pathway', 'saint', 'spoiler', 'tarot-club', 'minor-arcana', 'sick-church', 'psychology-alchemists', 'information-broker', 'intis-republic', 'trier', 'church-of-the-fool'], 218),
  ('npc-clemence-athana', 'Clémence Athana — Sealed Artifact 1-147, Sequence 4 Manipulator', 'npc', 'Clémence Athana was a Sequence 4 Manipulator of the Visionary Pathway, born into a magistrate''s family in Spahm Village, Zamet region of Upper Hornacis, Intis Republic. After passing through the Zamet Cloister in early adulthood, she entered Suhit University to study paleobiology, then stayed on as a faculty member researching mythical creatures. At twenty-nine she abruptly resigned and returned home, where a cascade of tragedies destroyed her family — her father drowned, her mother hanged herself, her siblings killed each other, and her sister vanished. A strange mental plague then swept through the village; by the time Purifiers identified her as the source, the infected were beyond saving and had to be purified entirely. Investigation revealed two spirits stitched within her soul: one that orchestrated the tragedies, and a second that could not cope and eventually went mad while fighting back instinctively. She was also found to carry a second, distinct corruption of unknown origin. Unable to be treated, she lost her mind entirely. In 1356 of the Fifth Epoch she was sealed, becoming Sealed Artifact 1-147 — a pale young woman in black nun''s attire, vacant-eyed, drifting between a lifeless stupor and instinctive resistance.', 'visionary', 5, null, ARRAY['Clémence Athana', '1-147'], ARRAY[4], ARRAY['visionary-pathway', 'saint', 'spoiler', 'intis-republic', 'sealed-artifact', 'paleobiologist', 'suhit-university', 'book-two'], 232),
  ('npc-ricciardo', 'Ricciardo — Misfortune Mage of the Fate Council', 'npc', 'Ricciardo is a Sequence 4 Misfortune Mage of the Wheel of Fortune Pathway and a sitting member of the Fate Council within the Life School of Thought, operating out of Oravi Island in the Loen Kingdom. Known by the honorific Councilor Ricciardo, he presents as a white-haired elder in a black short coat with a hard cane, bearing none of the obvious wrinkles one might expect. He teaches Roy King, who serves as his disciple.

His canon appearance in the narrative occurs during Book One when Gehrman Sparrow escorts Darkwill to a bridge near Saint Draco Cathedral to deliver the Die of Probability into Ricciardo''s custody. He employs his Misfortune Mage abilities to seal the artifact using fate manipulation with periodic boundary conditions, placing the Die in a perpetual state of slumber. As agreed compensation, on February 4, 1350, he attempts to augment Gehrman''s luck at a casino, but the working fails — Klein later concludes that the Gray Fog anchoring Sefirah Castle makes him immune to both luck and misfortune effects.', 'wheel-of-fortune', 5, null, ARRAY['Ricciardo', 'Roy King', 'Darkwill', 'Anderson Hood'], ARRAY[4], ARRAY['wheel-of-fortune-pathway', 'saint', 'spoiler', 'life-school-of-thought', 'fate-council', 'loen-kingdom', 'oravi-island', 'book-one', 'teacher'], 218),
  ('npc-lucca-brewster', 'Lucca Brewster — Bishop and Sequence 4 Prophet of the White Tower Pathway', 'npc', 'Lucca Brewster is a Sequence 4 Prophet of the White Tower pathway and a senior clergyman — bishop — of the Church of the God of Knowledge and Wisdom, stationed in West Balam on the Southern Continent. An elder in a white robe with inlaid brass lines, his completely white hair and gray-green eyes so deep they appear bottomless mark him as a figure of consequence.

He sought out Gehrman Sparrow after making a prophecy that foretold big trouble for himself; one of the people he would meet over the coming days would help him deal with it. During the 1350 World War, when Maysanchez''s West Balam mansion was attacked by Feynapotter military forces and the Church of the Earth Mother, Lucca nearly lost control in his mythical creature form. Klein lent Creeping Hunger to Audrey Hall and sent her to West Balam to help him. Afterward, Klein asked Lucca about an apocalypse prophecy, and Lucca relayed the prophecy of the God of Knowledge and Wisdom: the Apocalypse of the Fifth Epoch is set for 1368, and there will be a savior. At a later point Lucca was at the Holy Temple of Knowledge, studying anomalies on the 0-01 seal in hopes of deciphering secrets to invent new mystical techniques.', 'white-tower', 5, null, ARRAY['Lucca Brewster', 'Maysanchez', 'Klein Moretti', 'Audrey Hall'], ARRAY[4], ARRAY['white-tower-pathway', 'saint', 'spoiler', 'church-of-the-god-of-knowledge-and-wisdom', 'bishop', 'prophet', 'west-balam', 'southern-continent', '1350-world-war', 'apocalypse-prophecy'], 228),
  ('npc-floren-sauron', 'Floren Sauron — The Monster of Mental Sutures', 'npc', 'Floren Sauron walks the Red Priest Pathway, a scion of the storied Sauron Family and one of Roselle Gustav''s contemporaries in the Fifth Epoch''s Intis Republic. Canon confirms only that he is a Book One Saint; the wiki records no specific sequence rank or sequence name for him, so no exact station should be assumed. Arrogant with lineage, he coveted Roselle, declaring that to be made his subordinate beneath the great Sauron Family would be a "gift," and boasted that his uncanny resemblance to his great-great-grandfather granted him a keener path toward becoming a High-Sequence Beyonder. Roselle understood the peril he did not: High-Sequence Beyonder characteristics carry the mental imprints of their former owners, and one who advances through them without excising that imprint suffers identity dissociation — slowly transformed into a creature stitched together at the soul, as though the characteristic''s dead master were resurrecting inside his flesh. When Roselle saw him again, Floren had changed utterly, a different person wearing the same name; the promotion had taken him. "Some monsters are physical sutures," Roselle wrote, "while he is a monster of mental sutures" — a description, not a title he claimed. His vital status remains unknown.', 'red-priest', 5, null, ARRAY['Floren Sauron'], ARRAY[4], ARRAY['red-priest-pathway', 'spoiler', 'sauron-family', 'intis-republic', 'book-one-saint', 'saint'], 225),
  ('npc-gandalf', 'Gandalf — The Research Society President', 'npc', 'Gandalf is the codename of the founder and President of the Curly-Haired Baboons Research Society, and a Saint of the Twilight Giant Pathway. His exact station within the Saint tier is unrecorded — the wiki leaves his sequence name as unknown. A transmigrator carried into this world from the Modern Era, he appears within the Society as a half-giant of the Feysac Empire, endowed with a giant''s bloodline, towering to 2.4 meters beneath a plain linen hood, gripping a Skull Buster magic staff. He is a research-focused talent with an insatiable thirst for mystical knowledge, a taste for liquor, and an investigative eye that misses no detail; only Loki ever fully unraveled his true pathway, which others mistook for White Tower, Paragon, or Hermit traits. He introduced the Law of Beyonder Characteristics Indestructibility to the Society, hinted at the Law of Convergence, and established its Review Committee, leading its Academy Faction. Ally to Lumian Lee and enemy of the April Fool''s group, he arrived at Port Santa alongside Hela at Hidden Blade''s summons, effortlessly captured Bard at Milo Village, and impaled him with a straight sword condensed from Sunrise Gleam, claiming the semi-finished Ring of the Sea Queen as spoils. He remains alive.', 'twilight-giant', 5, null, ARRAY['Gandalf'], ARRAY[4], ARRAY['twilight-giant-pathway', 'spoiler', 'curly-haired-baboons-research-society', 'transmigrator', 'saint', 'feysac-empire'], 220),
  ('npc-maam-greed', 'Ma''am Greed — Councilor of the Persona Masks', 'npc', 'Ma''am Greed is the codename of one of the seven councilors of the Psychology Alchemists, a Beyonder who walks the Visionary Pathway. She holds the Greed Mask — one of the seven Persona Masks given to the organization''s councilors, each named for one of the seven deadly sins. The Greed Mask resembles the Gluttony Mask in appearance; beyond that likeness the corpus records no further description of it. From St. Millom, the capital of the Feysac Empire, she serves as the councilor placed in charge of that city, her true name hidden behind the mask that names her. She stands among the high-Sequence adepts of a pathway steeped in mind-reading and the weaving of perception. Living still in the Feysac north, she is a woman known to the world only by a sin worn as a title. The corpus keeps her deeds sparse and her history spare; what it affirms is her seat at that council, her Greed Mask, and her dominion over St. Millom — a councilor of the Psychology Alchemists, cloaked in Greed.', 'visionary', 5, null, ARRAY['Ma''am Greed'], ARRAY[4], ARRAY['visionary-pathway', 'spoiler', 'psychology-alchemists', 'persona-masks', 'feysac-empire', 'saint'], 175),
  ('npc-miss-sloth', 'Miss Sloth — Councilor of the Sloth Mask', 'npc', 'Miss Sloth is a codename, not a face — one of the seven councilors of the Psychology Alchemists, that loose fraternity of the Visionary Pathway which, through Hermes, became a division of the Twilight Hermit Order and has since moved under Adam''s will. Seven councilors each hold a Persona Mask named for one of the deadly sins; a President oversees all eight as the council''s head. Hers is the Sloth Mask: its eyes tightly shut, its mouth naturally drooping, as though the wearer forever sleeps. A Saint of the Visionary way — the Pathway of Dragons, of mind-reading, dream-weaving, and Imagination made real, its authority the balance of Justice — she is in charge of Feynapotter City, the capital of the Feynapotter Kingdom. Bearing her mask, she may pass into the Garden of Eden, the council''s hidden city seated in the sea of collective consciousness beneath every human mind. Alive still, a woman of unrevealed name, she carries the sardonic ease of her order: to Audrey Hall, who wears the Pride Mask, she needled, "Miss, you aren''t proud." Behind such lassitude waits whatever the Visionary way grants its Saints — unhurried, watchful, difficult to read.', 'visionary', 5, null, ARRAY['Miss Sloth'], ARRAY[4], ARRAY['visionary-pathway', 'saint', 'spoiler', 'psychology-alchemists', 'persona-masks', 'feynapotter-kingdom'], 208),
  ('npc-mr-envy', 'Mr. Envy — Bearer of the Envy Mask', 'npc', 'Mr. Envy is a codename, not a name — one of the seven councilors of the Psychology Alchemists, the secret order of Visionary Pathway Beyonders. He holds the Envy Mask, one of seven Persona Masks each named for a deadly sin and given to a councilor of the order; its eyes, ears, nose, and mouth are all slightly slanted, giving it a gloomy, sidelong temperament that is his only recorded face. From Tilisi City in the Intis Republic he governs his assigned domain as its responsible councilor. The Psychology Alchemists function as a division of the Twilight Hermit Order and operate under the will of Adam. Their council numbers eight in all — seven who hold a sin-named Persona Mask, each responsible for a city, and The President who oversees them. Through their masks the councilors may enter the Garden of Eden, the hidden city seated in the Sea of Collective Consciousness. A Saint of Book One, Mr. Envy remains alive.', 'visionary', 5, null, ARRAY['Mr. Envy'], ARRAY[4], ARRAY['visionary-pathway', 'book-one-saint', 'saint', 'spoiler', 'psychology-alchemists', 'twilight-hermit-order', 'persona-masks', 'intis-republic'], 185),
  ('npc-mr-gluttony', 'Mr. Gluttony — The Devouring Mask of Constant City', 'npc', 'Mr. Gluttony is a codename, one of the seven mask-bearing councilors of the Psychology Alchemists — the secret society that hoards the formulas of the Visionary Pathway and functions, through Hermes, as a division of the Twilight Hermit Order beneath Adam''s will. His true name goes unrecorded; he is known only by the Gluttony Mask he bears, one of the seven Persona Masks styled after the Seven Deadly Sins, each held by a councilor who governs a city. A Saint-tier Beyonder, he holds Constant City in the Loen Kingdom as his domain. He appears in a three-piece formal suit, a half top hat in hand and ten rings on his fingers, his mask split by a mouth torn wide toward the ears — perpetually open, as though it would swallow whatever his eyes could see. He speaks of researching the minds of ordinary creatures, taking rats, cockroaches, and crows for his subjects. At Audrey Hall''s first council meeting he reported the strange tremors of his region: Constant City rebuilt overnight, Belltaine''s citizens stripped of memory, rumors of the wandering archmage Merlin Hermes, a Fully Automatic Wishing Machine, and small beasts suddenly losing their souls. He remains alive.', 'visionary', 5, null, ARRAY['Mr. Gluttony'], ARRAY[4], ARRAY['visionary-pathway', 'saint', 'spoiler', 'psychology-alchemists', 'councilor', 'persona-mask', 'constant-city', 'loen-kingdom'], 225),
  ('npc-mr-lust', 'Mr. Lust — Councilor of the Psychology Alchemists', 'npc', 'Mr. Lust is the codename of one of the seven councilors of the Psychology Alchemists, a Beyonder of the Visionary Pathway who bears the Lust Mask — one of the seven Persona Masks named for the deadly sins and worn by that council''s masters. His domain is Trier, the capital of the Intis Republic. A living man residing in Trier, he wears a mask like Pride''s, save that its eyes have sunk to the middle of the nose, so that he seems to peer up at all others from beneath. The council numbers eight at any time: seven who hold a sin-mask, each responsible for a city and its surroundings, and The President who oversees all. When Mr. President sought volunteers to track the Mind Dragon near Hartlarkh Village in the Loen Kingdom, it was Mr. Lust who put forward Miss Pride and Mr. Gluttony, both Loen residents, to take up the hunt. He serves within the Psychology Alchemists — a loose, scholarly, and secretive division of the Twilight Hermit Order devoted to the endless exploration of the mind, its headquarters the dream-city Garden of Eden hidden in the Sea of Collective Consciousness. His pathway is that of psychological manipulation: the reading of minds, the discerning of emotions, and the weaving of dreams.', 'visionary', 5, null, ARRAY['Mr. Lust'], ARRAY[4], ARRAY['visionary-pathway', 'spoiler', 'psychology-alchemists', 'twilight-hermit-order', 'persona-mask', 'intis-republic', 'saint'], 220)
